  "organizer_id" int8 NOT NULL,
  "category_id" int2 NOT NULL,
  "title" text COLLATE "pg_catalog"."default" NOT NULL,
  "original_title" text COLLATE "pg_catalog"."default",
  "description" text COLLATE "pg_catalog"."default" NOT NULL,
  "age_restriction" text COLLATE "pg_catalog"."default" NOT NULL DEFAULT 'all'::text,
  "age_description" text COLLATE "pg_catalog"."default",
  "duration_minutes" int4,
  "genre" text[] COLLATE "pg_catalog"."default" NOT NULL DEFAULT '{}'::text[],
  "lineup" text[] COLLATE "pg_catalog"."default" NOT NULL DEFAULT '{}'::text[],
  "image_url" text COLLATE "pg_catalog"."default",
  "trailer_url" text COLLATE "pg_catalog"."default",
  "refund_policy" text COLLATE "pg_catalog"."default",
  "is_featured" bool NOT NULL DEFAULT false,
  "event_type" text COLLATE "pg_catalog"."default" NOT NULL DEFAULT 'general_admission'::text,
  "status" text COLLATE "pg_catalog"."default" NOT NULL DEFAULT 'draft'::text,
  "moderation_status" text COLLATE "pg_catalog"."default" NOT NULL DEFAULT 'pending_review'::text,
  "review_note" text COLLATE "pg_catalog"."default",
  "seo_title" text COLLATE "pg_catalog"."default",
  "seo_description" text COLLATE "pg_catalog"."default",
  "created_at" timestamptz(6) NOT NULL DEFAULT now(),
  "updated_at" timestamptz(6) NOT NULL DEFAULT now(),
  "search_doc" tsvector GENERATED ALWAYS AS (
((((setweight(to_tsvector('simple'::regconfig, immutable_unaccent(COALESCE(title, ''::text))), 'A'::"char") || setweight(to_tsvector('simple'::regconfig, immutable_unaccent(COALESCE(original_title, ''::text))), 'A'::"char")) || setweight(to_tsvector('simple'::regconfig, immutable_unaccent(COALESCE(immutable_join(lineup), ''::text))), 'B'::"char")) || setweight(to_tsvector('simple'::regconfig, immutable_unaccent(COALESCE(immutable_join(genre), ''::text))), 'B'::"char")) || setweight(to_tsvector('simple'::regconfig, immutable_unaccent(COALESCE(description, ''::text))), 'C'::"char"))
) STORED,
  "category" text COLLATE "pg_catalog"."default" DEFAULT 'Âm nhạc'::text
);
