-- Indexes for users
CREATE UNIQUE INDEX IF NOT EXISTS "uq_users_phone" ON "public"."users" USING btree (
  "phone" COLLATE "pg_catalog"."default" "pg_catalog"."text_ops" ASC NULLS LAST
) WHERE phone IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS "uq_users_provider_subject" ON "public"."users" USING btree (
  "provider" COLLATE "pg_catalog"."default" "pg_catalog"."text_ops" ASC NULLS LAST,
  "provider_user_id" COLLATE "pg_catalog"."default" "pg_catalog"."text_ops" ASC NULLS LAST
) WHERE provider_user_id IS NOT NULL;
-- Indexes for event_categories
CREATE INDEX IF NOT EXISTS "idx_event_categories_label_vi" ON "public"."event_categories" USING btree (
  "label_vi" COLLATE "pg_catalog"."default" "pg_catalog"."text_ops" ASC NULLS LAST
);
CREATE UNIQUE INDEX IF NOT EXISTS "uq_event_categories_label_vi_normalized" ON "public"."event_categories" USING btree (
  lower(regexp_replace(TRIM(BOTH FROM label_vi), '\s+'::text, ' '::text, 'g'::text)) COLLATE "pg_catalog"."default" "pg_catalog"."text_ops" ASC NULLS LAST
);
