INSERT INTO "public"."organizers" ("id", "user_id", "display_name", "description", "logo_url", "status", "review_note", "applied_at", "approved_at", "approved_by", "created_at") VALUES
  (1, 2, 'NoToDo Entertainment', 'Đơn vị tổ chức sự kiện biểu diễn âm nhạc, hội thảo công nghệ và triển lãm chuyên nghiệp hàng đầu tại Việt Nam.', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1787022338/tixhub/organizers/1.jpg', 'approved', 'Đơn vị tổ chức chính thức được kiểm duyệt và chứng nhận.', '2026-03-19 03:30:16.651188+00', '2026-03-20 03:30:16.651188+00', 1, '2026-03-19 03:30:16.651188+00'),
  (2, 5, 'Pending Organizer Corp', 'Công ty Cổ phần Sự kiện và Truyền thông Sáng tạo Trẻ. Chuyên tổ chức workshop nghệ thuật và hội chợ ẩm thực.', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546328/tixhub/organizers/2.png', 'pending', 'Hồ sơ đang chờ Admin đối soát giấy phép ĐKKD và tài khoản ngân hàng thụ hưởng.', '2026-08-13 03:30:16.651188+00', NULL, NULL, '2026-08-13 03:30:16.651188+00'),
  (3, 6, 'Suspended Media Group', 'Tổ chức biểu diễn giải trí và sự kiện âm nhạc quy mô vừa.', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546330/tixhub/organizers/3.webp', 'suspended', 'Tài khoản bị tạm khóa do vi phạm chính sách hủy sự kiện không báo trước theo quy chế TixHub.', '2026-06-17 03:30:16.651188+00', '2026-06-22 03:30:16.651188+00', 1, '2026-06-17 03:30:16.651188+00'),
  (4, 7, 'IMDb (Internet Movie Database)', 'IMDb is the world''s most popular and authoritative source for movie, TV and celebrity content.', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546329/tixhub/organizers/4.png', 'approved', 'Verified Official IMDb Movie Data Partner', '2026-01-01 00:00:00+00', '2026-01-01 00:00:00+00', 1, '2026-01-01 00:00:00+00'),
  (5, 8, 'Moveek Cinema Platform', 'Moveek là nền tảng thông tin điện ảnh và đặt vé xem phim hàng đầu tại Việt Nam.', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1787022343/tixhub/organizers/5.png', 'approved', 'Verified Official Moveek Partner', '2026-01-01 00:00:00+00', '2026-01-01 00:00:00+00', 1, '2026-01-01 00:00:00+00'),
  (6, 9, 'CJ CGV Vietnam', 'CJ CGV là một trong những cụm rạp chiếu phim lớn nhất tại Việt Nam và toàn cầu.', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546329/tixhub/organizers/6.webp', 'approved', 'Verified Official CJ CGV Partner', '2026-01-01 00:00:00+00', '2026-01-01 00:00:00+00', 1, '2026-01-01 00:00:00+00'),
  (7, 10, 'CÔNG TY CỔ PHẦN HỆ SINH THÁI ĐẤU THẦU', NULL, NULL, 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (8, 11, 'Vietnam Airlines x SpaceSpeakers Group x Vietcetera', '5AM là sự kiện âm nhạc ngoài trời lúc 5 giờ sáng, lần đầu tiên được tổ chức vào tháng 01/2024 bởi Vietnam Airlines, SpaceSpeakers Group và Vietcetera, đã thu hút hơn 1500 khán giả tham gia vào các hoạt động thức tỉnh của cơ thể như chạy bộ, tập yoga và kết thúc bằng một bữa tiệc âm nhạc sôi động, hứng khởi để bắt đầu một ngày mới.', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546328/tixhub/organizers/2.png', 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (9, 12, 'Orchestars', 'OrcheStars không chỉ là một công ty âm nhạc, mà là một nhịp cầu nối đưa nhạc giao hưởng thoát khỏi khuôn khổ truyền thống, vươn mình đến những không gian mới. Chúng tôi không ngừng nỗ lực để đưa nhạc giao hưởng đến gần hơn với công chúng, biến những buổi trình diễn thành trải nghiệm sống động và đầy cảm hứng, vượt ra khỏi ranh giới của những khán phòng truyền thống. Bằng tư duy đổi mới, những chương trình sáng tạo và sự đồng hành cùng các nghệ sĩ tài năng, OrcheStars kiến tạo một thế giới nơi nhạc giao hưởng trở nên gần gũi, sống động và đầy sức hút.', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546330/tixhub/organizers/3.webp', 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (10, 13, 'D-DAY & SHOW', 'D-DAY ＆ SHOW is a cultural entertainment company specializing in the production and organization of concerts, festivals, and artistic events in South Korea, Vietnam and internationally', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546329/tixhub/organizers/4.png', 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (11, 14, 'Hoa Hậu Sinh Viên Hoà Bình Việt Nam 2025', 'Cuộc thi “Hoa Hậu Sinh Viên Hoà Bình Việt Nam 2025” là một sự kiện đặc sắc và hấp dẫn với format chương trình mới lạ, lần đầu tiên tại Việt Nam các sinh viên nữ đƣợc tham gia một cuộc thi lớn về sắc đẹp với quy mô toàn quốc.Cuộc thi nhằm tìm kiếm các đại sứ sinh viên “Xinh Đẹp - Trí Tuệ - Bản Lĩnh - Giàu lòng nhân ái và tinh thần yêu nước vì một Việt Nam hoà bình” Thông điệp chủ đạo “Sinh Viên Việt Nam viết tiếp câu chuyện Hòa Bình của dân tộc” The “MISS GRAND UNIVERSITY VIET NAM 2025” contest is a distinctive and compelling event featuring an innovative format. For the first time in Viet Nam, female university students are given the opportunity to participate in a large-scale, nationwide beauty pageant. The competition aims to identify student ambassadors who are “Beautiful – Intelligent – Courageous – Compassionate – Patriotic, devoted to a peaceful Viet Nam.” Core message: “Vietnamese students continue writing the nation’s story of peace.”', NULL, 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (12, 15, 'CTicketxVNPost', 'CTicket là đối tác phân phối online Bộ tem bưu chính "Kỷ niệm 80 năm Quốc khánh nước Cộng hòa xã hội chủ nghĩa Việt Nam (02/09/1945 - 02/09/2025)" được phát hành bởi Bộ Khoa học và Công nghệ, Họa sỹ thiết kế: Nguyễn Du (Tổng công ty Bưu điện Việt Nam). Đơn vị in ấn: Công ty Tem Bưu chính - Chi nhánh Tổng Công ty Bưu điện Việt Nam (VNPost). CTicket is the official online distribution partner for the commemorative stamp set “Celebrating the 80th Anniversary of the National Day of the Socialist Republic of Vietnam (September 2, 1945 – September 2, 2025)”, issued by the Ministry of Science and Technology and designed by artist Nguyen Du (Vietnam Post Corporation). Stamp Printing Company – Branch of Vietnam Post Corporation (VNPost)', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546329/tixhub/organizers/6.webp', 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (21, 24, 'Beshine Media', 'Là một trong những đơn vị hoạt động nổi bật trong lĩnh vực thời trang và giải trí tại Việt Nam. Công ty chuyên tổ chức các sự kiện về thời trang, âm nhạc, nghệ thuật và giải trí, mang đến những trải nghiệm văn hóa độc đáo và ấn tượng.', NULL, 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (22, 25, 'ALLACCESS', 'ALLACCESS, thành lập từ năm 2017, là công ty tổ chức sự kiện và giải trí với kinh nghiệm vững chắc và sự gắn bó lâu năm trong ngành. Công ty được đông đảo khán giả, đặc biệt là cộng đồng indie, tin tưởng nhờ khả năng tạo ra những sự kiện hấp dẫn và hợp tác cùng nhiều nghệ sĩ tài năng. ALLACCESS, founded in 2017, is an event and entertainment company with solid experience and long-standing industry commitment. The company has earned wide audience trust - especially within the indie community - through its engaging events and collaborations with talented artists.', NULL, 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (255, 258, 'KO’s Playlist', NULL, NULL, 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (13, 16, 'Hakuna Matata', 'Hakuna Matata tập trung vào việc lên kế hoạch và tổ chức các buổi hòa nhạc cũng như fanmeeting của nghệ sĩ quốc tế, với nguồn nghệ sĩ chủ lực đến từ Hàn Quốc, Thái Lan, châu Âu và Mỹ. Hoạt động kinh doanh của công ty chủ yếu bao phủ khu vực Đông Nam Á. Công ty có nhiều kinh nghiệm trong việc triển khai các dự án xuyên biên giới và cam kết mang đến những trải nghiệm giải trí ngoại tuyến chất lượng cao cho người hâm mộ, đồng thời cung cấp dịch vụ biểu diễn chuyên nghiệp ở nước ngoài cho các nghệ sĩ. Trong những năm gần đây, chúng tôi đã tổ chức thành công nhiều sự kiện biểu diễn tại Hồng Kông, Macau, Đài Loan, Bangkok, Seoul, Singapore và nhiều địa điểm khác. ----- Hakuna Matata focuses on planning and hosting international artist concerts and fanmeeting, with Korean, Thai, and European and American artist resources as its core. Its business mainly covers Southeast Asia. The company has rich experience in executing cross-border projects and is committed to creating high-quality offline entertainment experiences for fans, while providing professional overseas performance services for artists. In recent years, we have successfully held multiple performances in Hong Kong, Macau, Taiwan, Bangkok, Seoul, Singapore and other places.', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546328/tixhub/organizers/7.jpg', 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (14, 17, 'CAPTAIN BOY Entertainment', NULL, 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546329/tixhub/organizers/8.webp', 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (15, 18, 'CÔNG TY TNHH SOL7 ENTERTAINMENT', 'Thành lập vào đầu năm 2024, SOL7 Entertainment là công ty hoạt động trong lĩnh vực giải trí, hướng đến việc tạo ra những dự án nghệ thuật ý nghĩa và kết nối nghệ sĩ với khán giả. Dự án đầu tiên đánh dấu bước khởi đầu của công ty là Fan Meeting “CHẠM” - kỷ niệm 15 năm hoạt động nghệ thuật của nghệ sĩ Song Luân, được tổ chức nhằm tri ân người hâm mộ đã luôn đồng hành và ủng hộ anh trong suốt chặng đường sự nghiệp. Sự kiện hứa hẹn mang đến nhiều khoảnh khắc đặc biệt cùng những bất ngờ thú vị dành cho khán giả.', NULL, 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (16, 19, 'CHÀO SHOW', 'Chương trình nghệ thuật đặc sắc Chào Show tôn vinh âm nhạc Việt Nam qua 30 nhạc cụ dân tộc độc đáo, có thể nói là dàn nhạc cụ dân tộc đầy đủ và độc lạ nhất hiện nay trong nước, mà chỉ hành trình sưu tầm tái tạo nhạc cụ cũng đã là một câu chuyện kì thú. Với 12 chương nhạc mang đậm tinh thần âm nhạc dân gian, do Trần Mạnh Hùng, một trong những nhạc sĩ hàng đầu của nền khí nhạc Việt nam sáng tác riêng cho Chào Show, chương trình đưa khán giả vào hành trình khám phá các vùng miền từ Bắc vào Nam, thưởng thức Bản sắc Việt trong âm nhạc. Được đạo diễn bởi đạo diễn Tất Mi Loan. Một điểm độc đáo nữa của Chào Show là sự kết hợp ngoạn mục giữa âm nhạc, hình ảnh, và 8 món ăn chơi từ ẩm thực đặc trưng của từng vùng miền.&nbsp; Sân khấu Chào Show là nơi đầu tiên tại Việt Nam đầu tư Hệ thống âm thanh Immersive Audio, công nghệ âm thanh&nbsp; mới nhất hiện nay. Giải pháp công nghệ này cho phép người nghe trải nghiệm âm thanh 3D, và ngồi ở bất kì vị trí nào trong khán phòng lớn cũng thưởng thức được âm thanh&nbsp; như ngồi ở vị trí trung tâm.', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546330/tixhub/organizers/10.webp', 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (17, 20, 'M.A.B Media', 'M.A.B Media là đơn vị truyền thông và sản xuất sáng tạo chuyên cung cấp các giải pháp toàn diện về sự kiện, video production và xây dựng thương hiệu. Với đội ngũ giàu kinh nghiệm cùng tư duy sáng tạo hiện đại, M.A.B Media đồng hành cùng doanh nghiệp trong việc kiến tạo những trải nghiệm truyền thông khác biệt, từ các sự kiện quy mô lớn, lễ ra mắt sản phẩm, hội nghị khách hàng đến các dự án TVC, phim doanh nghiệp và nội dung số.', NULL, 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (18, 21, 'Da Nang 365 Introduction', 'Danang 365 is a reputable agency in Central Vietnam with deep marketing expertise, a strong local network, and close community ties. We own leading media platforms specialized in lifestyle, tourism, and entertainment in Da Nang, ensuring maximum visibility for the event among locals, expats, and international tourists. Danang 365 là đơn vị uy tín tại miền Trung, sở hữu thế mạnh về marketing, mạng lưới địa phương và kết nối cộng đồng. Chúng tôi vận hành nền tảng truyền thông và tổ chức sự kiện hàng đầu về lifestyle, du lịch và giải trí tại Đà Nẵng, giúp tối đa hóa độ nhận diện với cộng đồng địa phương, người nước ngoài và du khách quốc tế.', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546330/tixhub/organizers/12.webp', 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (19, 22, 'H2Q Dance Company – Vietnam', 'H2Q Dance Company – Vietnam là một công ty vũ đạo có trụ sở tại Việt Nam, tập trung vào việc kết hợp giữa múa đương đại và các thể loại street dance bằng phương pháp biên đạo đương đại. Công ty hướng đến việc kết nối các biên đạo quốc tế với các vũ công địa phương tại Việt Nam.', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546330/tixhub/organizers/13.jpg', 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (20, 23, 'Tổ chức bởi Bảo tàng Mỹ thuật Việt Nam, đồng tổ chức bởi Chuyện của Hà Nội và Hà Nội FM', 'Bảo tàng Mỹ thuật Việt Nam Được thành lập từ năm 1966, Bảo tàng Mỹ thuật Việt Nam là một trong những bảo tàng có vị trí quan trọng nhất trong việc lưu trữ, phát huy kho tàng di sản văn hoá nghệ thuật Việt Nam. Hiện nay, Bảo tàng lưu trữ 9 bảo vật quốc gia và gần 20.000 hiện vật, tác phẩm tiêu biểu gồm nhiều chất liệu đa dạng, với các loại hình phong phú. Chuyện của Hà Nội: Được ra mắt từ năm 2018, với tầm nhìn trở thành thương hiệu sáng tạo nội dung truyền cảm hứng về văn hóa hàng đầu Việt Nam, Chuyện của Hà Nội là nơi mà hơn 4 triệu độc giả đang được tiếp nguồn cảm hứng, tình yêu từ Thủ đô văn hiến. Hà Nội FM: Xuất phát từ kênh Podcast, Hà Nội FM phát triển trở thành nhóm dự án văn hoá chuyên tổ chức các sự kiện trải nghiệm nội dung mang đậm tinh thần Hà Nội: Đêm thơ trong thành phố, Workshop thơ, The Muse Night, … Hà Nội FM tích cực sáng tạo các sản phẩm du lịch văn hoá, thúc đẩy nền công nghiệp văn hoá địa phương.', NULL, 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (23, 26, 'GUT LABEL', NULL, 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546331/tixhub/organizers/17.webp', 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (24, 27, 'FANTASY SHOW', NULL, NULL, 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (25, 28, 'GAM Esports', 'GAM Esports là tổ chức thể thao điện tử hàng đầu Việt Nam, được thành lập năm 2013. Với hơn một thập kỷ đồng hành cùng cộng đồng game thủ, GAM không chỉ là một đội tuyển - mà là biểu tượng của Esport Việt Nam trên bản đồ thế giới. Tại Gameverse, GAM Esports chào bán BST Merchandise - nơi người hâm mộ có thể mang theo một phần tinh thần GAM trong cuộc sống hằng ngày. GAM Esports is Vietnam''s leading esports organization, founded in 2013. Over more than a decade, GAM has grown from a local team into a symbol of Vietnamese esports on the world stage - competing at the highest level across multiple titles. At Gameverse, GAM Esports will sell our Merchandise collection, giving fans a way to carry the GAM spirit with them every day.', NULL, 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (26, 29, 'VPBank x 8Wonder', '🔥 Tiếp nối "đêm mưa huyền thoại VPBank K-Star Spark, VPBank lần thứ hai cùng G-DRAGON viết tiếp giấc mơ thanh xuân G-DRAGON 2025 WORLD TOUR [Übermensch] in Hanoi, presented by VPBank, diễn ra tại Ocean City ngày 8/11/2025 và ngày 09/11/2025. Từ những khoảnh khắc thăng hoa đã trở thành ký ức, hành trình mới lại bắt đầu. Hãy cùng VPBank chào đón G-DRAGON trong một đêm diễn rực cháy – nơi Việt Nam sẽ ghi dấu là điểm đến đầy cảm xúc của âm nhạc toàn cầu.', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546331/tixhub/organizers/20.webp', 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (27, 30, 'BCNV - Mạng Lưới Ung Thư Vú Việt Nam', 'Mạng lưới ung thư vú Việt Nam” (BCNV) là một doanh nghiệp xã hội hoạt động không vì lợi nhuận, tiên phong trong lĩnh vực ung thư vú tại Việt Nam, được khởi xướng bởi bà Thương Sobey (1982 - 2015) - một bệnh nhân ung thư vú giai đoạn 4. BCNV hoạt động vì một Việt Nam tương lai không còn ai chết vì thiếu hiểu biết và thiếu sự giúp đỡ khi phải chiến đấu với ung thư/ ung thư vú.” Sứ mệnh của BCNV: - Nâng cao nhận thức cho cộng đồng qua việc cung cấp kiến thức khoa học và thông tin hữu ích, nhằm nâng cao ý thức bảo vệ sớm, tăng tỷ lệ phát hiện sớm ung thư vú ở Việt Nam. - Nâng cao chất lượng sống cho những người bị ảnh hưởng (trực tiếp và gián tiếp) bởi ung thư vú thông qua hoạt động hỗ trợ về thông tin, vật chất và tinh thần." "Breast Cancer Network Vietnam"" (BCNV) is a non-profit social enterprise, pioneering in the field of breast cancer in Vietnam. It was initiated by Ms. Thuong Sobey (1982–2015), a stage IV breast cancer patient. BCNV operates with the vision of a future Vietnam where no one dies due to a lack of knowledge or support when facing cancer—especially breast cancer. BCNV’s mission includes: Raising public awareness by providing scientific knowledge and useful information, aiming to promote early prevention and increase the early detection rate of breast cancer in Vietnam. Improving the quality of life for those directly and indirectly affected by breast cancer through informational, material, and emotional support.', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546332/tixhub/organizers/21.jpg', 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (28, 31, 'Sky Sounds Production', 'Sky Sounds Production là nhà sản xuất và phát hành tiên phong trong lĩnh vực âm nhạc bản địa đương đại. Với tinh thần gìn giữ và làm mới, Sky Sounds mang đến những dự án sáng tạo giàu bản sắc, kết nối truyền thống với khán giả trẻ và đưa âm nhạc Việt Nam vươn ra thế giới. Email: seeus@skysoundsproduction.vn', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546332/tixhub/organizers/22.webp', 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (29, 32, 'LA MARITZA – Music Sky Lounge', 'Hệ thống âm thanh L - Acoustics đẳng cấp thế giới. View trọn vẹn thành phố Đà Lạt lung linh về đêm. Mái che toàn cảnh – thoải mái tận hưởng, không lo thời tiết', NULL, 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (30, 33, 'PHÒNG TRÀ BẾN THÀNH', NULL, 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546332/tixhub/organizers/24.webp', 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (31, 34, 'Hanwha Life Esports​', 'Hanwha Life Esports (HLE) là đội tuyển eSports chuyên nghiệp được thành lập bởi Hanwha Life vào năm 2018, hiện đang vận hành đội tuyển thủ League of Legends (LoL). Sau chức vô địch LCK Mùa Hè 2024, đội tiếp tục giành ngôi vương tại LCK Cup và First Stand 2025, qua đó vươn mình trở thành một trong những đội tuyển hàng đầu với năng lực cạnh tranh mạnh mẽ trên đấu trường quốc tế. ㅤ Bên cạnh đó, dưới tầm nhìn “LIFEPLUS – Gia tăng giá trị cuộc sống” của Hanwha Life, đội tuyển đang dẫn đầu một nền văn hóa eSports mới bằng cách mang đam mê và nguồn cảm hứng đến cuộc sống thường ngày của người hâm mộ trên toàn thế giới. ㅤ Trong năm 2026, với khẩu hiệu “Beyond the Challenge”, đội đặt mục tiêu mở rộng nền tảng của ngành eSports vượt ra ngoài phạm vi Hàn Quốc tiến đến toàn cầu và tạo dựng thời kỳ hoàng kim mới. Thông tin chi tiết về đội tuyển có thể xem tại trang web chính thức (www.hle.kr) cùng các kênh mạng xã hội chính thức như YouTube và Instagram (@hle.official).', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546332/tixhub/organizers/25.webp', 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (32, 35, 'HMZ Entertainment', NULL, 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546332/tixhub/organizers/26.webp', 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (33, 36, 'DC Agency', 'DC Agency là đơn vị có kinh nghiệm dày dạn trong hoạt động sản xuất, tổ chức biểu diễn, truyền thông, quảng cáo và quản lý talent. DC Agency đã từng tổ chức thành công loạt sự kiện, liveshow, concert, họp báo cho các nghệ sĩ hàng đầu showbiz Việt như ca sĩ Đàm Vĩnh Hưng, Như Quỳnh, Phương Uyên… Chất lượng sản xuất chương trình đã được ghi nhận qua thành công của nhiều dự án nổi bật: The Portrait Live Concert Hà Nội và Hạ Long (Đàm Vĩnh Hưng), The Show Vietnam, Liveshow Dấu Ấn Phương Uyên … DC Agency luôn cập nhật xu hướng, nâng cao chất lượng dịch vụ và là đối tác sản xuất chương trình, quảng cáo, truyền thông đáng tin cậy của các nhãn hàng và các nghệ sĩ.', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546333/tixhub/organizers/27.jpg', 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (289, 292, 'Passive Digital Income Club', NULL, NULL, 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (34, 37, 'Vietnam AI Film 2026', 'Ban Tổ chức Cuộc thi sáng tạo nội dung bằng trí tuệ nhân tạo, Vietnam AI Film lần 1 – 2026 “Huyền thoại Việt qua lăng kính AI”, với sứ mệnh kết nối công nghệ AI, điện ảnh sáng tạo và di sản văn hóa Việt Nam. Ban Tổ chức hướng đến việc tạo ra một sân chơi chuyên nghiệp, truyền cảm hứng cho cộng đồng sáng tạo kể lại những câu chuyện Việt bằng ngôn ngữ hình ảnh mới, đồng thời lan tỏa niềm tự hào văn hóa dân tộc trong thời đại số.', NULL, 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (35, 38, 'DOORI Group', 'DOORI Group (주) 두리 그룹', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546333/tixhub/organizers/29.jpg', 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (36, 39, 'The Consular Club of HCMC', NULL, NULL, 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (37, 40, 'Ani Mart', 'Từ nơi những câu chuyện hoạt hình bắt đầu - Những bản Cel Animation và phác thảo gốc đến từ Nhật Bản lần đầu tiên ra mắt tại Việt Nam cùng Ani Mart. Mỗi tác phẩm đều là nguyên tác độc đáo, thể hiện vẻ đẹp chân thực của nghệ thuật hoạt hình và giá trị sưu tầm quý giá.', NULL, 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (38, 41, 'La Musica', 'Điểm hẹn phim - nhạc - vui chơi cuối tuần, nơi nghệ thuật chuyên nghiệp và cộng đồng lại gần nhau hơn.', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546334/tixhub/organizers/32.webp', 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (39, 42, 'ALIVE', 'Là album phòng thu thứ 10 trong sự nghiệp, album “ALIVE” mở ra hành trình âm nhạc mà nghệ sĩ Hồ Trung Dũng dành trọn sự trân quý cho mọi thăng trầm của cuộc sống: từ những phút giây bình yên, niềm vui giản dị đến cả những góc khuất yếu lòng muốn lẩn trốn. Với 11 ca khúc, album là sự cộng hưởng hài hòa giữa nội lực mạnh mẽ và sự tinh tế nhẹ nhàng, dẫn dắt người nghe tìm thấy ánh sáng ngay giữa những ngã rẽ chông chênh nhất. Album gửi gắm đến khán giả thông điệp giản dị mà sâu sắc: chỉ cần dám hiện diện, dám đối diện với mỗi ngày trôi qua, chúng ta đã là người anh hùng của chính mình. Và sau tất cả, “ALIVE” đọng lại như một lời khẳng định dõng dạc nhưng rất đỗi dịu dàng rằng: mỗi người đều có quyền chọn con đường riêng - bởi chỉ cần được SỐNG, được hiện diện với chính mình, và luôn chọn yêu giữa những ngã rẽ, bạn đã là một người hùng theo cách rất riêng.', NULL, 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (40, 43, 'FestArt & Backstage', 'Đơn vị hiện thực hóa hành trình “Ngự Liên Thức Thủy”. Bằng tư duy sáng tạo kết hợp giữa công nghệ ánh sáng, âm nhạc hiện đại và hơi thở di sản, chúng tôi biến mỗi khoảnh khắc tại Ngày Hội Sen Huế 2026 thành một dấu ấn trải nghiệm đa giác quan không thể quên. The creative force behind the "Ngự Liên Thức Thủy" journey. By blending innovative lighting, modern music, and the spirit of heritage, we transform every moment at the Hue Lotus Festival 2026 into an unforgettable, multi-sensory experience.', NULL, 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (41, 44, 'Dế Mèn Creative', 'Dế Mèn Creative là đơn vị sáng tạo nghệ thuật – văn hoá, khởi nguồn từ nhạc kịch “Dế Mèn Ngoại Truyện”, lấy cảm hứng từ nhân vật quen thuộc - chú Dế Mèn. Chúng tôi theo đuổi giấc mơ xây dựng một hệ sinh thái giải trí – giáo dục đa phương tiện, nơi nghệ thuật đại chúng không chỉ mang tính giải trí mà còn gieo mầm những giá trị sống, nuôi dưỡng tâm hồn trẻ và kết nối các thế hệ gia đình Việt. Với định hướng giữ gìn hồn Việt, nâng tầm chuẩn mực quốc tế, Dế Mèn Creative kết hợp âm nhạc, sân khấu, truyền thông và cộng đồng để tạo nên những sản phẩm sáng tạo vừa gần gũi vừa hiện đại, mang khát vọng đưa hình ảnh Việt vươn xa trong kỷ nguyên mới.', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546334/tixhub/organizers/35.png', 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (42, 45, 'Lacus Entertainment', NULL, 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546334/tixhub/organizers/36.jpg', 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (43, 46, 'Dàn Nhạc Giao Hưởng Sài Gòn (SPO)', 'Là một trong những dàn nhạc tư nhân tiên phong tại Việt Nam, Dàn nhạc Giao hưởng Sài Gòn (Saigon Philharmonic Orchestra - SPO) không ngừng khẳng định vị thế trong việc kết nối công chúng với những giá trị nghệ thuật hàn lâm đỉnh cao. Với tinh thần đổi mới và hội nhập, SPO đã góp phần đưa các tác phẩm kinh điển - từ giao hưởng, thính phòng đến những vở diễn kết hợp đa phương tiện - đến gần hơn với khán giả Việt Nam. Đồng hành cùng những tên tuổi lớn trong nước và quốc tế, SPO không chỉ là dàn nhạc biểu diễn, mà còn là cầu nối văn hóa, kiến tạo những trải nghiệm nghệ thuật mang tầm vóc quốc tế cho công chúng Việt. Trong sự kiện đặc biệt lần này, SPO hân hạnh là đơn vị đồng tổ chức đưa Eifman Ballet - tượng đài ballet đương đại nước Nga - đến Việt Nam lần đầu tiên trong lịch sử.', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546335/tixhub/organizers/37.webp', 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (44, 47, 'ASIIX', NULL, 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546335/tixhub/organizers/38.webp', 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (45, 48, 'Ravolution Asia', 'Ravolution Asia được thành lập bởi Công ty Cổ phần Anternation vào năm 2016. Sau gần 10 năm hình thành và phát triển, nền tảng Ravo Festivals, với trọng tâm là thương hiệu Ravolution Music Festival, đã không ngừng lớn mạnh. Năm 2026 đánh dấu cột mốc quan trọng: “Một thập kỷ hành trình kiến tạo Lễ hội Âm nhạc Việt Nam” – RAVO 10 YEARS, kỷ niệm 10 năm của Ravolution Asia. Ravolution Asia was founded by Anternation Joint Stock Company in 2016. Over nearly a decade of growth and development, the Ravo Festivals platform—centered around the Ravolution Music Festival brand—has steadily expanded. The year 2026 marks a significant milestone: “A Decade of Shaping Vietnam’s Music Festival Journey” – RAVO 10 YEARS, celebrating the 10th anniversary of Ravolution Asia.', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546335/tixhub/organizers/39.jpg', 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (72, 75, 'D''Hoi - Hoiana Summer Fest 2026', '.', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546340/tixhub/organizers/66.png', 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (46, 49, 'CÔNG TY TNHH RHYDER ENTERTAINMENT', 'Thành lập nửa đầu năm 2024, Công ty TNHH RHYDER ENTERTAINMENT tự hào là đơn vị tổ chức chính thức cho DỰ ÁN BÍ MẬT - dự án đầu tiên đánh dấu bước khởi đầu đầy hứa hẹn của công ty. Với tầm nhìn sáng tạo và đam mê mang âm nhạc đến gần hơn với công chúng, RHYDER Entertainment đã quy tụ một đội ngũ sản xuất chuyên nghiệp, dày dạn kinh nghiệm trong lĩnh vực giải trí.', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546335/tixhub/organizers/40.jpg', 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (47, 50, 'Saigon Sake Fest ’25', 'Saigon Sake Fest ’25 là sự kiện được đồng tổ chức bởi GOOD TIMES MARKETING và Flava, mang đến một không gian giao lưu văn hoá Việt - Nhật dành cho những người trẻ năng động, yêu thích trải nghiệm và kết nối. Lễ hội là nơi âm nhạc, ẩm thực và phong cách sống hòa quyện, tạo nên một đêm rộn ràng đầy cảm xúc. Từ những màn trình diễn live, khu ẩm thực mang tinh thần Izakaya đến các hoạt động tương tác, mọi khoảnh khắc tại Saigon Sake Fest đều được thiết kế để khơi gợi cảm hứng, mở rộng kết nối và lan tỏa năng lượng tích cực của cộng đồng yêu văn hóa Nhật Bản.', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546336/tixhub/organizers/41.webp', 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00');
INSERT INTO "public"."organizers" ("id", "user_id", "display_name", "description", "logo_url", "status", "review_note", "applied_at", "approved_at", "approved_by", "created_at") VALUES
  (48, 51, 'ISE - International Solution for Event', 'ISE - International Solution for Event là nhà tổ chức lễ hội quốc tế chuyên nghiệp kiến tạo nên những sự kiện quy mô và giàu trải nghiệm. Với các loại hình đa dạng như Lễ hội Âm nhạc, Văn hóa - Du lịch, Thể thao và Thời trang, ISE tập trung tôn vinh giá trị văn hóa và xu hướng hiện đại thông qua từng sự kiện được đầu tư bài bản, hướng đến dấu ấn khác biệt và tầm vóc quốc tế. ISE – International Solution for Event is a professional international festival organizer, creating large-scale and immersive event experiences. With a diverse portfolio including Music, Cultural &amp; Tourism, Sports, and Fashion Festivals, ISE celebrates cultural values and modern trends through well-executed events, delivering distinctive impressions at an international standard.', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546336/tixhub/organizers/42.webp', 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (49, 52, '+84 Entertainment', 'Công ty TNHH +84 Entertainment', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546336/tixhub/organizers/43.png', 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (50, 53, 'WINGS', NULL, NULL, 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (51, 54, 'DREAMS ENTERTAINMENT', 'DreamS Entertainment là một trong những công ty giải trí hàng đầu tại Việt Nam, hoạt động trong lĩnh vực quản lý nghệ sĩ, sản xuất âm nhạc, nội dung sáng tạo và tổ chức sự kiện. Với sứ mệnh phát triển và nâng tầm nghệ sĩ, DreamS Entertainment luôn nỗ lực mang đến những sản phẩm chất lượng, sáng tạo và truyền cảm hứng. Là ngôi nhà của JSOL, Hoàng Duyên, Sơn.K DreamS không chỉ hỗ trợ nghệ sĩ phát triển sự nghiệp mà còn kết nối họ với khán giả thông qua các dự án nghệ thuật, sự kiện...', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546337/tixhub/organizers/45.jpg', 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (52, 55, 'TỎA', 'Giữa lòng Sài Gòn, TOẢ là không gian nghệ thuật tiên phong kết hợp giữa nghệ thuật đương đại và công nghệ trình chiếu hiện đại, mang​ đến trải nghiệm đa giác quan đẳng cấp quốc tế. Công nghệ AR/VR cùng hệ thống trình chiếu đa chiều biến mỗi tác phẩm nghệ thuật​ thành một thế giới sống động, nơi người xem có thể bước vào không gian sáng tạo, khám phá nghệ thuật bằng thị giác, thính giác và​ xúc giác. Với các màn hình LED vòm, hệ thống âm thanh 360° và trình chiếu mapping tương tác, TOẢ đưa nghệ thuật vượt ra khỏi giới hạn​ truyền thống, mở ra một không gian sáng tạo mới mẻ, nơi cảm xúc và ý tưởng được kết nối thông qua công nghệ.', NULL, 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (53, 56, 'Trinity Live x 2Res x Flava', 'Flava Live là nền tảng nghệ thuật, thể thao, văn hóa và sáng tạo vì cộng đồng, Flava không chỉ lan tỏa cảm hứng sống đầy màu sắc mà còn kiến tạo những trải nghiệm đậm “hương vị cuộc sống.” Flava Live is a community-driven platform that celebrates art, sports, culture, and creativity. Beyond spreading vibrant inspiration, Flava creates immersive experiences that capture the true “flavor of life.” Liên hệ/ Contact: Email: business@sundatefestival.vn Fanpage: https://www.facebook.com/sundatefestival', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546337/tixhub/organizers/47.webp', 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (54, 57, 'GSN Production', NULL, NULL, 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (55, 58, 'HAPPY Space', 'HAPPY Space - Không gian nghệ thuật hạnh phúc dành cho gia đình có nhiều sản phẩm nghệ thuật dành cho Mẹ và Bé.', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546338/tixhub/organizers/49.webp', 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (56, 59, 'THE NEXT', 'THE NEXT là một tập thể mang trong mình tình yêu âm nhạc, khao khát tạo nên những đêm diễn bùng nổ, nơi cộng đồng yêu dòng nhạc Indie, Underground, cùng những thể loại Pop/R&B hiện đại tại Việt Nam thật sự kết nối. Chúng tôi không ngừng sáng tạo, để mỗi sự kiện không chỉ là một đêm nhạc, mà còn là một dấu ấn không thể quên! ------- THE NEXT is a collective driven by a deep love for music, passionate about creating explosive live shows—where the Indie, Underground, and modern Pop/R&B communities in Vietnam truly connect. We constantly push the boundaries of creativity, ensuring that each event is not just a concert, but an unforgettable experience!', NULL, 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (57, 60, 'The Wandering Rose', 'Một đóa hồng lạc giữa mộng mơ – The Wandering Rose là đêm nhạc mang đến không gian lãng mạn, tinh tế với những bản tình ca ngọt ngào, sâu lắng. Đây là dịp để khán giả được hòa mình vào những giai điệu đẹp, gặp gỡ các nghệ sĩ được yêu mến và tận hưởng một buổi tối trọn vẹn cảm xúc tại Hà Nội.', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546338/tixhub/organizers/51.jpg', 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (92, 95, 'Vie Channel', 'VieChannel: Đơn vị sản xuất', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546345/tixhub/organizers/86.png', 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (290, 293, 'Paul Chuter', NULL, NULL, 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (58, 61, 'THUNDER ARENA - ĐẤU TRƯỜNG SẤM', 'Đấu Trường Sấm Concert – Nghệ thuật quy mô lớn, tổ chức bởi SIXSOL - Đồng tổ chức GANGA - Tài trợ bởi MAYogu. Hướng đến việc kiến tạo một sân khấu đỉnh cao, nơi âm nhạc, công nghệ và cảm xúc hội tụ.', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546338/tixhub/organizers/52.webp', 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (59, 62, 'CÔNG TY TNHH CÔNG NGHỆ VĂN HÓA T&T', NULL, NULL, 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (60, 63, 'Music Tab', 'Music Tab Là nền tảng kinh doanh âm nhạc hàng đầu Việt Nam - nơi kết nối những tài năng trong nước với sân khấu quốc tế, đồng thời đưa nghệ sĩ toàn cầu đến gần hơn với nhịp sống âm nhạc sôi động của Việt Nam. Music Tab cung cấp giải pháp toàn diện cho nghệ sĩ từ hoạt động kinh doanh âm nhạc kĩ thuật số sôi động đến những sân khấu màu sắc, từ kinh doanh khai thác bản quyền bản ghi, dịch vụ nghệ sĩ đến các giải pháp marketing kỹ thuật số tiên tiến Ở Music Tab, chúng tôi không chỉ chạy theo xu hướng mà còn tạo nên nhịp điệu của ngày mai', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546338/tixhub/organizers/54.webp', 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (61, 64, 'DINH LUU MEDIA', NULL, NULL, 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (62, 65, 'Viet Charm Show', 'VietCharm show - Đan di sản - Chạm cảm xúc Đánh thức giá trị Việt Hành trình tìm lại những nét đẹp di sản qua lăng kính đương đại, VietCharm chính thức ra mắt mang đến một không gian nghệ thuật trình diễn và ẩm thực độc bản', NULL, 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (63, 66, 'VPBank', 'Từ năm 2019 đến nay, VPBank đã tổ chức và đồng hành cùng hàng chục giải chạy bộ quy mô lớn dành cho cộng đồng, khẳng định vị thế là một trong những doanh nghiệp tiên phong và giàu kinh nghiệm trong việc thúc đẩy phong trào chạy bộ tại Việt Nam. Các giải chạy do VPBank tổ chức đã thu hút hàng chục nghìn vận động viên chuyên nghiệp và bán chuyên tham gia. Bên cạnh đó, VPBank cũng sở hữu câu lạc bộ chạy bộ doanh nghiệp lớn nhất Việt Nam với hơn 2.000 thành viên. Since 2019, VPBank has organized and partnered with dozens of large-scale community running events, affirming its position as one of the pioneering and most experienced corporations in promoting the running movement in Vietnam. The races organized by VPBank have attracted tens of thousands of professional and semi-professional runners. In addition, VPBank also operates the largest corporate running club in Vietnam, with more than 2,000 members.', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546338/tixhub/organizers/57.webp', 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (64, 67, 'VPBank x T1 Team', 'Viết tiếp câu chuyện đồng hành cùng những huyền thoại, VPBank mang đến sự kiện eSport lớn nhất Việt Nam "VPBank presents eSport Festival: Legends Unite" với sự xuất hiện của biểu tượng eSport toàn cầu - Đội tuyển Liên Minh Huyền Thoại (LMHT) T1. Lần đầu tiên, người hâm mộ Việt Nam sẽ được gặp gỡ đội hình thi đấu T1 với Faker, Oner, Doran, Keria và Peyz - và chứng kiến trận showmatch lịch sử giữa các tuyển thủ hàng đầu Việt Nam vs huyền thoại T1. Sự kiện diễn ra trong hai ngày 20–21/12/2025 tại Trung tâm Triển lãm Việt Nam (VEC), Hà Nội, hứa hẹn là dấu ấn không thể quên của cộng đồng game thủ Việt.', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546339/tixhub/organizers/58.webp', 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (65, 68, 'FESTART & BACKSTAGE', 'Sự kết hợp giữa những người làm sự kiện mang trong mình tình yêu âm nhạc và khao khát tạo nên những lễ hội bùng nổ — nơi cộng đồng giới trẻ cùng những người đam mê dòng nhạc hiện đại (EDM, Pop, Hip-hop) tại Việt Nam thật sự kết nối. Chúng tôi không ngừng sáng tạo để mỗi sự kiện không chỉ là một đêm nhạc, mà còn là một dấu ấn trải nghiệm không thể quên! A collaboration between event creators who share a deep love for music and a passion for creating explosive festivals — where the youth and modern music communities (EDM, Pop, Hip-hop) in Vietnam truly connect. We constantly push the boundaries of creativity, ensuring that each event is not just a concert, but an unforgettable experience!', NULL, 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (66, 69, 'WANXING ENTERTAINMENT', 'Updating', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546339/tixhub/organizers/60.png', 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (67, 70, 'MULTIMEDIA JSC', 'MULTIMEDIA JSC Được thành lập vào năm 2005, Công ty Cổ phần Truyền thông Đa phương tiện Multimedia JSC đã nhanh chóng phát triển và trở thành một trong những công ty truyền thông và sản xuất chương trình truyền hình hàng đầu của Việt Nam. Với mạng lưới đối tác rộng khắp trên toàn cầu, Multimedia JSC đã và đang chứng minh vị thế, uy tín, chất lượng qua các chương trình do MultiMedia JSC sản xuất như: Vietnam’s Next Top Model, The Face Vietnam, Tuần Lễ Thời Trang Quốc Tế Việt Nam.', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546339/tixhub/organizers/61.png', 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (68, 71, 'French Chamber of Commerce and Industry in Vietnam - CCIFV', 'CCI France Vietnam (CCIFV) is the first French-Vietnamese business network. It is a non-profit association that brings together the vast majority of French organizations operating in Vietnam, along with numerous Vietnamese companies engaged in business with France. CCIFV is part of the worldwide network of Chambers of Commerce and Industry France International (CCI France International), which brings together 120 chambers in 95 countries.', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546339/tixhub/organizers/62.png', 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (69, 72, 'CÔNG TY TNHH WOLF ENTERTAINMENT', 'Chịu trách nhiệm sản xuất CÔNG TY TNHH WOLF ENTERTAINMENT', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546339/tixhub/organizers/63.jpg', 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (70, 73, 'VietNam Sightseeing', 'Đại lý Vé Xe Bus 2 tầng SightSeeing trải nghiệm Thành Phố cực đẹp từ trên cao.', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546340/tixhub/organizers/64.png', 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (71, 74, 'Sân Khấu Quốc Thảo', 'Được thành lập vào năm 2017, biểu diễn nghệ thuật và đào tạo diễn viên', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546340/tixhub/organizers/65.jpg', 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (373, 376, 'ekoparty security conference', NULL, NULL, 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (73, 76, 'La Maison Du Chocolat', 'Bảo tàng La Maison du Chocolat được thành lập dựa trên mô hình kết hợp trưng bày – trải nghiệm – ẩm thực – thương mại, nhằm tạo ra một không gian văn hóa sống động thay vì một bảo tàng tĩnh truyền thống. Giới thiệu văn hóa cacao Việt Nam: Truyền tải câu chuyện về cacao Việt – từ thổ nhưỡng đến con người. Đặc biệt, bảo tàng chú trọng giáo dục chuyên sâu cho du khách nước ngoài, giúp họ hiểu rõ hành trình di sản của cây cacao Việt Nam trên bản đồ thế giới, từ những bước chân đầu tiên của giống cây', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546341/tixhub/organizers/67.png', 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (74, 77, 'THE SOCIALITE', 'THE SOCIALITE - ĐƠN VỊ TỔ CHỨC MINISHOW “YÊU NHAU NỬA NGÀY” Đêm nhạc “Yêu Nhau Nửa Ngày” được thực hiện bởi The Socialite, đơn vị hoạt động trong lĩnh vực tổ chức sự kiện, giải trí và sản xuất các trải nghiệm nghệ thuật dành cho cộng đồng yêu âm nhạc. Với định hướng mang đến những chương trình chỉn chu về cảm xúc và trải nghiệm, The Socialite mong muốn cùng LASONG tạo nên một đêm nhạc đáng nhớ tại Thanh Hóa trong mùa hè này.', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546341/tixhub/organizers/68.png', 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (75, 78, 'Absolute Media', 'Absolute Media là đơn vị tổ chức sự kiện và sản xuất truyền thông hàng đầu. Cung cấp giải pháp toàn diện trong tổ chức sự kiện và sản xuất nội dung truyền thông, đảm bảo tính chuyên nghiệp, chính xác và sáng tạo từ giai đoạn ý tưởng đến hiện thực. Absolute Media là đơn vị tổ chức các sự kiện âm nhạc, giải trí nổi bật như Live Concert Giao Hưởng Mùa Yêu, League of Legends Esports, Festival Ninh Bình 2025,..', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546341/tixhub/organizers/69.png', 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (76, 79, 'REGAL GROUP', 'Regal Group là thương hiệu bất động sản hạng sang hàng đầu Việt Nam, tiên phong kiến tạo những kiệt tác kiến trúc độc bản, hội tụ tinh hoa di sản văn hóa bản địa với chuẩn mực đẳng cấp quốc tế lần đầu tiên có mặt tại Việt Nam.', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546342/tixhub/organizers/70.png', 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (77, 80, 'ARCHER MEDIA', 'ARCHER MEDIA', NULL, 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (78, 81, 'Dolphin HaLong Cruise', 'Biểu tượng du thuyền giải trí all-in-one trong ngày đầu tiên trên Vịnh Hạ Long, tiên phong mang đến những trải nghiệm đẳng cấp, tinh tế và giàu cảm xúc.', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546342/tixhub/organizers/72.png', 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (79, 82, 'CÔNG TY TNHH BÓNG RỔ CẦN THƠ', 'Thành lập năm 2016 tại Cần Thơ, Cantho Catfish là đội bóng rổ chuyên nghiệp mang đậm bản sắc miền Tây, với linh vật Cá Basa tượng trưng cho tinh thần mạnh mẽ, bền bỉ và khát vọng vươn lên. Sau 10 mùa giải VBA, đội khẳng định vị thế hàng đầu với 3 lần vào Chung kết liên tiếp giai đoạn 2017–2019 và chức vô địch năm 2018. Mùa 2024, Cantho Catfish trở lại ấn tượng với ngôi Á quân VBA và tiếp tục vào Playoffs mùa 2025 ở vị trí Top 3.', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546342/tixhub/organizers/73.png', 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (80, 83, 'LOA LOA Culture & Dining Show.', 'LOA LOA Culture &amp; Dining Show.', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546343/tixhub/organizers/74.png', 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (81, 84, '1900 Le Théâtre', '1900 Le Théâtre là điểm đến quen thuộc để giải trí cuối tuần, là nơi tụ tập của những người yêu nghệ thuật. Không chỉ nổi tiếng trong giới trẻ thủ đô, 1900 còn là thương hiệu nightlife thời thượng với các trang fan hâm mộ trên Facebook, Instagram, TikTok với hơn 800.000 người theo dõi, khẳng định vị trí số 1 ngành Nightlife tại Việt Nam. Năm 2023, 1900 đứng thứ 40 trong danh sách Top 100 Club của tạp chí nổi tiếng DJ Mag, là đại diện duy nhất của Việt Nam trong danh sách này.', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546342/tixhub/organizers/75.png', 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (82, 85, 'Đối tác sản xuất của SSL', 'Updating…', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546342/tixhub/organizers/76.png', 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (83, 86, 'VINPEARL', 'The leading hospitality brand in Vietnam with luxury hotels &amp; resorts in Vietnam&#39;s top destinations.', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546343/tixhub/organizers/77.jpg', 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (84, 87, 'YeaH1 Group x 1Production', 'YeaH1 Group x 1Production', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546343/tixhub/organizers/78.png', 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
