  (87, 90, 'YEAH1 x 1PRO x TECHCOMBANK', 'YEAH1', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546344/tixhub/organizers/81.png', 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (88, 91, 'Vi21 MEDIA', 'CÔNG TY CỔ PHẦN SỰ KIỆN VÀ TRUYỀN THÔNG VIỆT 21 (Vi21 MEDIA)', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546344/tixhub/organizers/82.jpg', 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
