  (374, 377, 'CYT OFICIAL - CAPACITACIONES', NULL, NULL, 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
  (93, 96, 'VIET VISION', 'VIET VISION COMMUNICATION – ENTERTAINMENT – CREATIVE JSC', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785546345/tixhub/organizers/87.png', 'approved', 'Verified Organizer', '2026-05-18 03:30:16.651188+00', '2026-05-19 03:30:16.651188+00', 1, '2026-05-18 03:30:16.651188+00'),
