  (55, 'hoa-minzy-fan-concert-bac-bling-47-55', 32, 1, 'HOÀ MINZY FAN CONCERT: BẮC BLING', NULL, 'Chưa có mô tả', 'all', 'Mọi lứa tuổi', 120, '{"Âm nhạc"}', '{"Ban tổ chức"}', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785426453/tixhub/events/EVT000049.webp', NULL, 'Chính sách hoàn tiền của ban tổ chức.', 'f', 'general_admission', 'on_sale', 'approved', NULL, 'HOÀ MINZY FAN CONCERT: BẮC BLING | TixHub', 'Chưa có mô tả...', '2026-05-18 03:30:16.651188+00', '2026-05-18 03:30:16.651188+00', 'Âm nhạc'),
  (56, 'huong-sac-giai-nhan-48-56', 33, 1, 'HƯƠNG SẮC GIAI NHÂN', NULL, 'DC Agency là đơn vị có kinh nghiệm dày dạn trong hoạt động sản xuất, tổ chức biểu diễn, truyền thông, quảng cáo và quản lý talent. DC Agency đã từng tổ chức thành công loạt sự kiện, liveshow, concert, họp báo cho các nghệ sĩ hàng đầu showbiz Việt như ca sĩ Đàm Vĩnh Hưng, Như Quỳnh, Phương Uyên… Chất lượng sản xuất chương trình đã được ghi nhận qua thành công của nhiều dự án nổi bật: The Portrait Live Concert Hà Nội và Hạ Long (Đàm Vĩnh Hưng), The Show Vietnam, Liveshow Dấu Ấn Phương Uyên … DC Agency luôn cập nhật xu hướng, nâng cao chất lượng dịch vụ và là đối tác sản xuất chương trình, quảng cáo, truyền thông đáng tin cậy của các nhãn hàng và các nghệ sĩ.', 'all', 'Mọi lứa tuổi', 120, '{"Âm nhạc"}', '{"Ban tổ chức"}', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785426453/tixhub/events/EVT000050.webp', NULL, 'Chính sách hoàn tiền của ban tổ chức.', 'f', 'general_admission', 'on_sale', 'approved', NULL, 'HƯƠNG SẮC GIAI NHÂN | TixHub', 'DC Agency là đơn vị có kinh nghiệm dày dạn trong hoạt động sản xuất, tổ chức biểu diễn, truyền thông...', '2026-05-18 03:30:16.651188+00', '2026-05-18 03:30:16.651188+00', 'Âm nhạc'),
  (57, 'huyen-thoai-viet-qua-lang-kinh-ai-49-57', 34, 7, 'HUYỀN THOẠI VIỆT QUA LĂNG KÍNH AI', NULL, 'Ban Tổ chức Cuộc thi sáng tạo nội dung bằng trí tuệ nhân tạo, Vietnam AI Film lần 1 – 2026 “Huyền thoại Việt qua lăng kính AI”, với sứ mệnh kết nối công nghệ AI, điện ảnh sáng tạo và di sản văn hóa Việt Nam. Ban Tổ chức hướng đến việc tạo ra một sân chơi chuyên nghiệp, truyền cảm hứng cho cộng đồng sáng tạo kể lại những câu chuyện Việt bằng ngôn ngữ hình ảnh mới, đồng thời lan tỏa niềm tự hào văn hóa dân tộc trong thời đại số.', 'all', 'Mọi lứa tuổi', 120, '{"Kinh doanh"}', '{"Ban tổ chức"}', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785426454/tixhub/events/EVT000051.webp', NULL, 'Chính sách hoàn tiền của ban tổ chức.', 'f', 'general_admission', 'on_sale', 'approved', NULL, 'HUYỀN THOẠI VIỆT QUA LĂNG KÍNH AI | TixHub', 'Ban Tổ chức Cuộc thi sáng tạo nội dung bằng trí tuệ nhân tạo, Vietnam AI Film lần 1 – 2026 “Huyền th...', '2026-05-18 03:30:16.651188+00', '2026-05-18 03:30:16.651188+00', 'Kinh doanh'),
