  (184, 'graffiti-art-workshop-with-artist-luis-del-valle-176-184', 185, 13, 'Graffiti Art Workshop with Artist Luis Del Valle', NULL, 'The Smithsonian''s Anacostia Community Museum documents and preserves communities’ memories, struggles, and successes, and offers a platform where diverse voices and cultures can be heard.', 'all', 'Mọi lứa tuổi', 120, '{Khác}', '{"Ban tổ chức"}', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785426475/tixhub/events/EVT000178.jpg', NULL, 'Chính sách hoàn tiền của ban tổ chức.', 'f', 'general_admission', 'on_sale', 'approved', NULL, 'Graffiti Art Workshop with Artist Luis Del Valle | TixHub', 'The Smithsonian''s Anacostia Community Museum documents and preserves communities’ memories, struggl...', '2026-05-18 03:30:16.651188+00', '2026-05-18 03:30:16.651188+00', 'Khác'),
  (185, 'green-drinks-dc-s-june-happy-hour-177-185', 186, 7, 'Green Drinks DC''s June Happy Hour!', NULL, 'Green Drinks DC is a monthly social series for environmentally-minded professionals, students, and enthusiasts in the nation’s capital.We have a lively mixture of people from NGOs, academia, government and business. So come along and you’ll be made welcome. It’s a great way of catching up with people you know, making new contacts, and building a network. Bring your friends and tell your network: Green Drinks DC’s events are never something you want to miss!Our goal is to keep these events simple and fun, and we a thrilled that people have found employment, made friends, developed new ideas, done deals, and had moments of serendipity while spending time with Green Drinks DC.Cheers!The Green Drinks DC Committee', 'all', 'Mọi lứa tuổi', 120, '{"Kinh doanh"}', '{"Ban tổ chức"}', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785426475/tixhub/events/EVT000179.jpg', NULL, 'Chính sách hoàn tiền của ban tổ chức.', 'f', 'general_admission', 'on_sale', 'approved', NULL, 'Green Drinks DC''s June Happy Hour! | TixHub', 'Green Drinks DC is a monthly social series for environmentally-minded professionals, students, and e...', '2026-05-18 03:30:16.651188+00', '2026-05-18 03:30:16.651188+00', 'Kinh doanh'),
