  (204, 'sustainable-architecture-heritage-design-with-wakako-tokunaga-196-204', 204, 13, 'Sustainable Architecture & Heritage Design with Wakako Tokunaga', NULL, 'The Japan Information & Culture Center (JICC) is a part of thePublic Affairs Section of the Embassy of Japan in Washington D.C. The JICC''s goal is to promote better understanding of Japan and Japanese culture by providing a wide range of information andeventsto the American public.We are located on the ground floor of 1150 18th St. in downtown Washington, D.C. Visitors to our center will enjoy the modern Japanese ambiance and the many events held in our facilities, which include a 130-seat auditorium.', 'all', 'Mọi lứa tuổi', 120, '{Khác}', '{"Ban tổ chức"}', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785426479/tixhub/events/EVT000198.jpg', NULL, 'Chính sách hoàn tiền của ban tổ chức.', 'f', 'general_admission', 'on_sale', 'approved', NULL, 'Sustainable Architecture & Heritage Design with Wakako Tokunaga | TixHub', 'The Japan Information & Culture Center (JICC) is a part of thePublic Affairs Section of the Embassy ...', '2026-05-18 03:30:16.651188+00', '2026-05-18 03:30:16.651188+00', 'Khác'),
  (205, 'svpg-product-masterclass-197-205', 205, 7, 'SVPG Product Masterclass', NULL, 'The Silicon Valley Product Group (SVPG)was created to share our senior level experience and knowledge of best practices with our clients. Our partners are all industry veterans, who have each held executive level positions at major Silicon Valley firms where they have been instrumental in the development of leading products. We are not career consultants; we started SVPG to share what we’ve learned.', 'all', 'Mọi lứa tuổi', 120, '{"Kinh doanh"}', '{"Ban tổ chức"}', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785426479/tixhub/events/EVT000199.jpg', NULL, 'Chính sách hoàn tiền của ban tổ chức.', 'f', 'general_admission', 'on_sale', 'approved', NULL, 'SVPG Product Masterclass | TixHub', 'The Silicon Valley Product Group (SVPG)was created to share our senior level experience and knowledg...', '2026-05-18 03:30:16.651188+00', '2026-05-18 03:30:16.651188+00', 'Kinh doanh'),
