  (259, 'the-spice-must-flow-a-live-action-roleplaying-game-251-259', 257, 13, 'The Spice Must Flow: A Live-Action Roleplaying Game', NULL, 'Goblin Market on Lincoln Ave specializes in manga, manhwa, danmei, comics, independent RPGs, queer stories, unique crafts, & curiosities.', 'all', 'Mọi lứa tuổi', 120, '{Khác}', '{"Ban tổ chức"}', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785426488/tixhub/events/EVT000254.jpg', NULL, 'Chính sách hoàn tiền của ban tổ chức.', 'f', 'general_admission', 'on_sale', 'approved', NULL, 'The Spice Must Flow: A Live-Action Roleplaying Game | TixHub', 'Goblin Market on Lincoln Ave specializes in manga, manhwa, danmei, comics, independent RPGs, queer s...', '2026-05-18 03:30:16.651188+00', '2026-05-18 03:30:16.651188+00', 'Khác'),
  (260, 'the-world-we-want-artist-led-workshop-with-olly-costello-252-260', 258, 13, 'The World We Want Artist-Led Workshop with Olly Costello', NULL, 'Jane Addams Hull-House Museum(JAHHM)draws upon the legacy of international peace activist and feminist, Jane Addams, and other social reformers who worked, alongside their immigrant neighbors, to create social change on the Near West Side of Chicago during the Progressive Era. The Museum preserves and develops the original Hull-House site for the interpretation and continuation of the historic settlement house vision. Exhibitions and public programs elevate histories of activism, progressive education and democratic principles of participation and exchange, and connect them to present-day social justice issues.', 'all', 'Mọi lứa tuổi', 120, '{Khác}', '{"Ban tổ chức"}', 'https://res.cloudinary.com/dutskr8jo/image/upload/v1785426488/tixhub/events/EVT000255.jpg', NULL, 'Chính sách hoàn tiền của ban tổ chức.', 'f', 'general_admission', 'on_sale', 'approved', NULL, 'The World We Want Artist-Led Workshop with Olly Costello | TixHub', 'Jane Addams Hull-House Museum(JAHHM)draws upon the legacy of international peace activist and femini...', '2026-05-18 03:30:16.651188+00', '2026-05-18 03:30:16.651188+00', 'Khác'),
